-- ============================================================
-- ORION-HARDENING FASE 2 · ETAPA 2 — Menor privilégio em RPCs DEFINER · 2026-07-19
-- Base: FASE 1 (R2) + HOTFIX A.0 (declarou 1.116 fns anon). Esta migration fecha
-- o vetor de MUTAÇÃO anônima nas funções DEFINER fora dos domínios já tratados.
-- Inventário vivo: 1005 DEFINER não-trigger exec. por anon; 421 mutam; 204 sem guarda.
-- Destas 204: 8 são superfície PÚBLICA legítima (interest-click/inquiry/order) → MANTIDAS;
-- 196 não têm caminho anônimo legítimo (grep .rpc em src+Edge) → REVOKE anon.
-- 2 são financeiras (split de pagamento) → REVOKE anon+authenticated (só service_role).
-- +2 leituras sensíveis (mp_get_admin_overview, is_admin_user) → REVOKE anon.
-- service_role e owner mantidos: motor/cron/trigger/Edge intactos (chamadas internas
-- de DEFINER e triggers executam como owner, independentes do grant).
-- SEM DDL de tabela/função. SEM regra de negócio. Idempotente. SQL Editor.
-- ============================================================

-- BLOCO 1 · 2 financeiras (split de pagamento): revoke anon+authenticated
DO $$ BEGIN EXECUTE 'REVOKE EXECUTE ON FUNCTION public.create_motoboy_split_transaction(uuid,numeric,numeric,uuid,uuid,uuid,text,jsonb) FROM PUBLIC, anon, authenticated'; EXECUTE 'GRANT EXECUTE ON FUNCTION public.create_motoboy_split_transaction(uuid,numeric,numeric,uuid,uuid,uuid,text,jsonb) TO service_role'; EXCEPTION WHEN undefined_function OR undefined_object THEN RAISE WARNING 'ausente: create_motoboy_split_transaction(uuid,numeric,numeric,uuid,uuid,uuid,text,jsonb)'; END $$;
DO $$ BEGIN EXECUTE 'REVOKE EXECUTE ON FUNCTION public.release_service_payment_split(uuid,uuid,numeric,numeric) FROM PUBLIC, anon, authenticated'; EXECUTE 'GRANT EXECUTE ON FUNCTION public.release_service_payment_split(uuid,uuid,numeric,numeric) TO service_role'; EXCEPTION WHEN undefined_function OR undefined_object THEN RAISE WARNING 'ausente: release_service_payment_split(uuid,uuid,numeric,numeric)'; END $$;

