SELECT
 (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
   WHERE n.nspname='public' AND p.prosecdef AND p.prorettype<>'trigger'::regtype
     AND has_function_privilege('anon',p.oid,'EXECUTE')
     AND (p.prosrc ~* 'insert into|update |delete from|truncate')
     AND NOT (p.prosrc ~* 'auth\.uid|is_admin|is_platform_admin|has_role|assert|guard')) AS anon_mut_noguard_restante,
 (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
   WHERE n.nspname='public' AND p.prosecdef AND p.prorettype<>'trigger'::regtype
     AND has_function_privilege('anon',p.oid,'EXECUTE')
     AND (p.proname ~* 'split|payment_split|motoboy_split')) AS anon_fin_split_restante;
